impl protocol::MutationKind<Snap, Op> for RenameNode {
    fn label(&self) -> protocol::LocalizedLabel {
        protocol::LocalizedLabel::native(&format!("Rename {} to {}", self.id, self.name), &format!("{} in {} umbenennen", self.id, self.name))
    }
}

impl MutationKind<Snap, Op> for Toggle {
    fn label(&self) -> LocalizedLabel {
        match self.on {
            true => LocalizedLabel::native("Show", "Einblenden"),
            false => LocalizedLabel::native("Hide", "Ausblenden"),
        }
    }
}

impl CompositeMutationKind<Counter, CounterMutation> for AddTwice {
    fn label(&self) -> crate::LocalizedLabel {
        crate::LocalizedLabel::native("Add twice", "Zweimal hinzufügen")
    }
}

impl SemanticMutation<Counter> for Unpublished {
    fn label(&self) -> crate::LocalizedLabel {
        crate::LocalizedLabel::native("Add to the counter", "")
    }
}

impl MutationKind<Snap, Op> for SetName {
    fn label(&self) -> LocalizedLabel {
        LocalizedLabel::data(self.name.clone())
    }
}

impl MutationKind<Snap, Op> for Patch {
    fn label(&self) -> LocalizedLabel {
        LocalizedLabel::native(&self.print_op(), &self.print_op())
    }
}

impl protocol::SemanticMutation<Puzzle2dPlaySnapshot> for Puzzle2dMutation {
    fn label(&self) -> protocol::LocalizedLabel {
        <Self as protocol::SemanticMutation<Puzzle2dSnapshot>>::label(self)
    }
}

impl protocol::SemanticMutation<NoConfig> for NoConfigMutation {
    fn label(&self) -> LocalizedLabel {
        match *self {}
    }
}

impl MutationKind<Snap, Op> for Storey {
    fn label(&self) -> LocalizedLabel {
        crate::labels::storey(self)
    }
}

impl ArtifactEditor for HtmlEditor {
    fn mutation_label(op: &Self::Mutation) -> Option<LocalizedLabel> {
        Some(protocol::SemanticMutation::label(op))
    }
}

impl Widget for Slider {
    fn label(&self) -> LocalizedLabel {
        LocalizedLabel::data("x")
    }
}
